settings.custom_css:
selector .elementor-widget-text-editor p { margin: 0; }
/* dorado de 3 tonos (solo color) */
selector .ak-doc-title .ak-g, selector .ak-doc-esp .elementor-heading-title { background-image: linear-gradient(#905532, #905532); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-doc-link .elementor-button-text, selector .ak-doc-link .elementor-button-icon i { background-image: linear-gradient(#905532, #905532); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-doc-link .elementor-button { border-image: linear-gradient(#905532, #905532) 1 !important; }
selector .ak-doc-card { --width: 100%; }
/* degradado oscuro bajo el texto de cada tarjeta (Figma, reforzado para legibilidad) */
selector .ak-doc-card { position: relative; overflow: hidden; }
selector .ak-doc-card::after { content: ""; position: absolute; inset: 0; pointer-events: none; z-index: 0;
  background: linear-gradient(to bottom, rgba(6,6,6,0) 44%, rgba(6,6,6,.82) 64%, rgba(6,6,6,.94) 76%, #060606 92%); }
selector .ak-doc-card > .e-con, selector .ak-doc-card > .elementor-element { position: relative; z-index: 1; }
/* posición fija como el Figma: el nombre empieza al 67% de la tarjeta y "Ver trayectoria" queda abajo */
selector .ak-doc-card > .e-con.ak-doc-body { position: absolute !important; top: 67%; bottom: 18px; left: 16px; right: 16px; width: auto !important; z-index: 1;
  display: flex !important; flex-direction: column; justify-content: flex-start; align-items: flex-start; }
selector .ak-doc-body .ak-doc-link { margin-top: auto !important; }
selector .ak-doc-flag img { display: block; }
selector .ak-doc-link .elementor-button { padding: 0 0 7px; border-bottom: 1px solid #905532; border-radius: 0; }
/* flechas */
selector .ak-doc-carousel .elementor-swiper-button { width: 56px; height: 56px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 17px; top: calc(50% - 21px) !important; transform: translateY(-50%); margin: 0; z-index: 3; cursor: pointer; transition: background .2s, color .2s; }
selector .ak-doc-carousel .elementor-swiper-button svg { width: 17px; height: 17px; }
selector .ak-doc-carousel .elementor-swiper-button-prev { left: -166px !important; right: auto !important; background: transparent; border: 1px solid transparent; background: linear-gradient(#090909, #090909) padding-box, linear-gradient(#905532, #905532) border-box; color: #905532; fill: #905532; }
selector .ak-doc-carousel .elementor-swiper-button-next { right: -166px !important; left: auto !important; background: linear-gradient(#905532, #905532); border: 1px solid #905532; color: #060606; fill: #060606; }
selector .ak-doc-carousel .elementor-swiper-button-prev:hover { background: #F3F5F7; color: #100600; fill: #100600; }
selector .ak-doc-carousel .elementor-swiper-button-next:hover { background: #905532; }
/* puntos: uno por docente */
selector .ak-doc-carousel .swiper-pagination { position: static !important; display: flex; justify-content: center; align-items: center; gap: 11px; height: 42px; padding-top: 32px; transform: none !important; width: 100% !important; }
selector .ak-doc-carousel .swiper-pagination-bullet { width: 10px; height: 10px; margin: 0 !important; opacity: 1; background: rgba(255,255,255,.2); }
selector .ak-doc-carousel .swiper-pagination-bullet-active { background: linear-gradient(#905532, #905532); }
@media (max-width: 1366px) {
  selector .ak-doc-carousel .elementor-swiper-button { width: 48px; height: 48px; top: calc(50% - 19px) !important; }
  selector .ak-doc-carousel .elementor-swiper-button-prev { left: -68px !important; }
  selector .ak-doc-carousel .elementor-swiper-button-next { right: -68px !important; }
  selector .ak-doc-carousel .swiper-pagination { height: 38px; padding-top: 28px; }
}
@media (max-width: 1024px) {
  selector .ak-doc-carousel .elementor-swiper-button { width: 44px; height: 44px; }
  selector .ak-doc-carousel .elementor-swiper-button-prev { left: -54px !important; }
  selector .ak-doc-carousel .elementor-swiper-button-next { right: -54px !important; }
}
@media (max-width: 767px) {
  selector { overflow: hidden; }
  selector .ak-doc-title br { display: none; }
  /* tarjeta centrada; la anterior y la siguiente asoman a los lados */
  selector .ak-doc-carousel .swiper { width: 76%; overflow: visible !important; margin-left: auto !important; margin-right: auto !important; }
  selector .ak-doc-carousel .elementor-swiper-button { width: 40px; height: 40px; top: calc(50% - 20px) !important; }
  selector .ak-doc-carousel .elementor-swiper-button-prev { left: -6px !important; }
  selector .ak-doc-carousel .elementor-swiper-button-next { right: -6px !important; }
  selector .ak-doc-carousel .swiper-pagination { height: 40px; padding-top: 24px; }
}
selector .ak-doc-card > .e-con.ak-doc-body { top: 53%; }
selector .ak-doc-card::after { background: linear-gradient(to bottom, rgba(6,6,6,0) 40%, rgba(6,6,6,.6) 56%, rgba(6,6,6,.75) 70%, rgba(6,6,6,.85) 90%); }
@media (max-width: 1366px) { selector .ak-doc-card > .e-con.ak-doc-body { top: 44%; } selector .ak-doc-card::after { background: linear-gradient(to bottom, rgba(6,6,6,0) 32%, rgba(6,6,6,.6) 47%, rgba(6,6,6,.75) 62%, rgba(6,6,6,.85) 88%); } }
@media (max-width: 1024px) { selector .ak-doc-card > .e-con.ak-doc-body { top: 47%; } }
@media (max-width: 932px) { selector .ak-doc-card > .e-con.ak-doc-body { top: 43%; } }
@media (max-width: 767px) { selector .ak-doc-card > .e-con.ak-doc-body { top: 45%; } }
@media (max-width: 1024px) { selector { overflow: hidden; } }

@media (max-width: 767px) {
  /* una tarjeta a todo el ancho del contenedor, sin asomar las vecinas; se cambia deslizando o con los puntos */
  selector .ak-doc-carousel .swiper { width: 100% !important; overflow: hidden !important; margin-left: 0 !important; margin-right: 0 !important; }
  selector .ak-doc-carousel .elementor-swiper-button { display: none !important; }
  /* la tarjeta toma la proporción de la foto (768 × 1076) para que no se amplíe ni se corte la cara */
  selector .ak-doc-card { height: auto !important; min-height: 0 !important; --min-height: 0px; aspect-ratio: 768 / 1076; }
  /* el texto se apoya en el borde inferior: queda igual en cualquier ancho de mobile */
  selector .ak-doc-card > .e-con.ak-doc-body { top: auto !important; }
  selector .ak-doc-body .ak-doc-link { margin-top: 18px !important; }
}
@media (min-width: 768px) and (max-width: 1366px) {
  /* laptop y tablet: el texto se apoya en el borde inferior, como en desktop con el margen del nombre */
  selector .ak-doc-card > .e-con.ak-doc-body { top: auto !important; }
  selector .ak-doc-body .ak-doc-link { margin-top: 18px !important; }
}
/* degradado más corto: sin la bio, el texto ocupa solo el cuarto inferior de la tarjeta */
selector .ak-doc-card::after { background: linear-gradient(to bottom, rgba(6,6,6,0) 55%, rgba(6,6,6,.6) 70%, rgba(6,6,6,.75) 82%, rgba(6,6,6,.85) 100%); }
@media (max-width: 1366px) { selector .ak-doc-card::after { background: linear-gradient(to bottom, rgba(6,6,6,0) 52%, rgba(6,6,6,.6) 68%, rgba(6,6,6,.75) 82%, rgba(6,6,6,.85) 100%); } }
